// Guard-only specialization of the original unsigned overflow test.
// Every constant is the unique floor((UINT64_MAX-rowBytes)/(N-1)).
// Unsupported geometry keeps the original generic expression; the outer
// observed-shape guard still refuses unsupported geometry before math.
template <ushort Bits, ushort GroupSize>
inline bool row_stride_bounds(constant FlashAffineParams &p) {
  if (Bits == 4 && GroupSize == 64 && p.input_size == 2560 && p.output_size == 10240)
    return p.weight_row_stride_bytes <= 1801615789990189ul &&
        p.parameter_row_stride_bytes <= 1801615789990189ul;
  if (Bits == 4 && GroupSize == 64 && p.input_size == 2560 && p.output_size == 12288)
    return p.weight_row_stride_bytes <= 1501322053691670ul &&
        p.parameter_row_stride_bytes <= 1501322053691670ul;
  if (Bits == 4 && GroupSize == 64 && p.input_size == 6144 && p.output_size == 2560)
    return p.weight_row_stride_bytes <= 7208575253501191ul &&
        p.parameter_row_stride_bytes <= 7208575253501192ul;
  if (Bits == 5 && GroupSize == 64 && p.input_size == 2560 && p.output_size == 10240)
    return p.weight_row_stride_bytes <= 1801615789990189ul &&
        p.parameter_row_stride_bytes <= 1801615789990189ul;
  if (Bits == 5 && GroupSize == 128 && p.input_size == 6144 && p.output_size == 2560)
    return p.weight_row_stride_bytes <= 7208575253501191ul &&
        p.parameter_row_stride_bytes <= 7208575253501192ul;
  if (Bits == 5 && GroupSize == 128 && p.input_size == 2560 && p.output_size == 6144)
    return p.weight_row_stride_bytes <= 3002888502964276ul &&
        p.parameter_row_stride_bytes <= 3002888502964276ul;
  if (Bits == 6 && GroupSize == 64 && p.input_size == 2560 && p.output_size == 6144)
    return p.weight_row_stride_bytes <= 3002888502964276ul &&
        p.parameter_row_stride_bytes <= 3002888502964276ul;
  if (p.output_size <= 1) return false;
  return p.weight_row_stride_bytes <=
      (~ulong(0) - ulong(p.input_size) * Bits / 8) / (p.output_size - 1) &&
      p.parameter_row_stride_bytes <=
      (~ulong(0) - ulong(p.input_size / GroupSize) * 2) / (p.output_size - 1);
}
